<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { changePassword, getProfile, updateProfile, uploadAvatar, type UserProfile } from '../auth/authApi'
import { getMyCoupons } from '../api'
const emit = defineEmits<{ back: []; passwordChanged: [] }>()
const profile = ref<UserProfile | null>(null), nickname = ref(''), currentPassword = ref(''), newPassword = ref(''), selectedFile = ref<File | null>(null), loading = ref(true), savingProfile = ref(false), uploadingAvatar = ref(false), changingPassword = ref(false), avatarFailed = ref(false), message = ref(''), error = ref(''), coupons = ref<{id:string;couponId:string;status:string;termEndAt?:string}[]>([]), couponsLoaded = ref(false)
const initials = computed(() => (profile.value?.nickname || profile.value?.email || profile.value?.phone || '观').trim().slice(0, 1).toUpperCase())
const avatarUrl = computed(() => profile.value?.avatarUrl || '')
async function load(){loading.value=true;error.value='';try{profile.value=await getProfile();nickname.value=profile.value.nickname||''}catch{error.value='个人资料加载失败，请稍后重试。'}finally{loading.value=false}}
async function saveProfile(){savingProfile.value=true;error.value='';message.value='';try{profile.value=await updateProfile(nickname.value);nickname.value=profile.value.nickname||'';message.value='资料已更新'}catch{error.value='资料更新失败，请检查昵称后重试。'}finally{savingProfile.value=false}}
function chooseAvatar(event:Event){selectedFile.value=(event.target as HTMLInputElement).files?.[0]||null;error.value=''}
async function saveAvatar(){if(!selectedFile.value){error.value='请先选择一张头像。';return};const file=selectedFile.value;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>2*1024*1024){error.value='头像需为 JPG、PNG 或 WebP，且不超过 2 MB。';return};uploadingAvatar.value=true;error.value='';message.value='';try{profile.value=await uploadAvatar(file);selectedFile.value=null;avatarFailed.value=false;message.value='头像已更新'}catch{error.value='头像上传失败，请稍后重试。'}finally{uploadingAvatar.value=false}}
async function savePassword(){if(!currentPassword.value||!newPassword.value){error.value='请输入当前密码和新密码。';return};changingPassword.value=true;error.value='';message.value='';try{await changePassword(currentPassword.value,newPassword.value);emit('passwordChanged')}catch{error.value='密码修改失败，请确认当前密码和新密码格式。'}finally{changingPassword.value=false}}
onMounted(load)
async function loadCoupons(){try{coupons.value=(await getMyCoupons()).items;couponsLoaded.value=true}catch{error.value='优惠券加载失败，请稍后重试。'}}
</script>
<template><section class="profile-panel"><div class="admin-heading profile-heading"><div><p class="eyebrow">ACCOUNT</p><h1>个人中心</h1><p class="profile-subtitle">管理你的 Cloud Ticketing 账户资料。</p></div><button class="secondary-btn profile-back" @click="emit('back')">返回活动</button></div><p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="message" class="profile-success" role="status">{{message}}</p><p v-if="loading">正在加载个人资料...</p><template v-else-if="profile"><div class="profile-grid"><section class="profile-card profile-overview"><div class="profile-avatar-wrap"><img v-if="avatarUrl&&!avatarFailed" :src="avatarUrl" alt="用户头像" class="profile-avatar" @error="avatarFailed=true"><span v-else class="profile-avatar profile-avatar-fallback" data-testid="avatar-fallback">{{initials}}</span><label class="secondary-btn profile-upload-label"><input data-testid="avatar-input" type="file" accept="image/jpeg,image/png,image/webp" @change="chooseAvatar">选择头像</label><button class="primary-btn profile-upload-btn" data-testid="upload-avatar" :disabled="uploadingAvatar||!selectedFile" @click="saveAvatar">{{uploadingAvatar?'上传中...':'上传头像'}}</button></div><div class="profile-identity"><h2>{{profile.nickname||'现场观众'}}</h2><p>{{profile.status}}</p><small>ID · {{profile.id}}</small></div><div class="profile-readonly"><label>手机号<input :value="profile.phone||'未绑定'" readonly></label><label>邮箱<input :value="profile.email||'未绑定'" readonly></label><label>注册时间<input :value="profile.createdAt?new Date(profile.createdAt).toLocaleString():'—'" readonly></label></div></section><div class="profile-stack"><section class="profile-card"><div class="profile-card-title"><div><p class="eyebrow">PROFILE</p><h2>基本资料</h2></div></div><form class="profile-form" @submit.prevent="saveProfile"><label>昵称<input v-model="nickname" data-testid="nickname-input" maxlength="120" placeholder="现场见面时怎么称呼你？"></label><button class="primary-btn compact" data-testid="save-profile" :disabled="savingProfile">{{savingProfile?'保存中...':'保存资料'}}</button></form></section><section class="profile-card"><div class="profile-card-title"><div><p class="eyebrow">SECURITY</p><h2>修改密码</h2></div></div><form class="profile-form" @submit.prevent="savePassword"><label>当前密码<input v-model="currentPassword" data-testid="current-password" type="password" autocomplete="current-password"></label><label>新密码<input v-model="newPassword" data-testid="new-password" type="password" autocomplete="new-password"></label><p class="profile-hint">8-128 位，需包含大写、小写字母和数字。</p><button class="primary-btn compact" data-testid="change-password" :disabled="changingPassword">{{changingPassword?'提交中...':'修改密码并退出'}}</button></form></section><section class="profile-card coupon-card"><div class="profile-card-title"><div><p class="eyebrow">PROMOTION</p><h2>我的优惠券</h2></div><button class="secondary-btn" type="button" data-testid="load-coupons" @click="loadCoupons">{{couponsLoaded?'刷新':'查看'}}</button></div><div v-if="couponsLoaded" class="coupon-list"><p v-for="coupon in coupons" :key="coupon.id">{{coupon.couponId}} <span class="muted">{{coupon.status}} · {{coupon.termEndAt||'长期有效'}}</span></p><p v-if="!coupons.length" class="muted">暂无优惠券</p></div></section></div></div></template></section></template>
